            [140, 320], [280, 480], [420, 260], [680, 360], [840, 240], [940, 460],
            [180, 820], [320, 720], [760, 780], [900, 860],
            [120, 1260], [260, 1420], [800, 1340], [920, 1220], [860, 1540]
